func Test_RegoTextOutput(t *testing.T) {
	fooBarDeny := hd.Doc(`
		{
			"path":[
				{"type":"var","value":"data"},
				{"type":"string","value":"policy"},
				{"type":"string","value":"foo"},
				{"type":"string","value":"bar"},
				{"type":"string","value":"deny"}
			],
			"annotations":{
				"scope":"rule",
				"title":"Rule title",
				"description":"Rule description",
				"custom":{
					"short_name":"rule_title"
				}
			}
		}
	`)

	tests := []struct {
		name     string
		source   string
		annJson  string
		template string
		expected string
		err      error
	}{
		{
			name:     "Smoke test",
			source:   "spam.io/bacon-bundle",
			annJson:  fooBarDeny,
			template: "text",
			expected: hd.Doc(`
				# Source: spam.io/bacon-bundle

				policy.foo.bar.rule_title (deny)
				https://enterprisecontract.dev/docs/ec-policies/foo_policy.html#bar__rule_title
				Rule title
				Rule description
				--
			`),
			err: nil,
		},
		{
			name:     "Smoke test",
			source:   "spam.io/bacon-bundle",
			annJson:  fooBarDeny,
			template: "names",
			expected: "policy.foo.bar.rule_title\n",
			err:      nil,
		},
		{
			name:     "Smoke test",
			source:   "spam.io/bacon-bundle",
			annJson:  fooBarDeny,
			template: "short-names",
			expected: "foo.bar.rule_title\n",
			err:      nil,
		},
		{
			name:   "With collections",
			source: "spam.io/bacon-bundle",
			annJson: hd.Doc(`
				{
					"path":[
						{"type":"var","value":"data"},
						{"type":"string","value":"policy"},
						{"type":"string","value":"foo"},
						{"type":"string","value":"bar"},
						{"type":"string","value":"deny"}
					],
					"annotations":{
						"scope":"rule",
						"title":"Rule title",
						"description":"Rule description",
						"custom": {
							"collections": ["eggs"]
						}
					}
				}
			`),
			template: "text",
			expected: hd.Doc(`
				# Source: spam.io/bacon-bundle

				policy.foo.bar. (deny)
				Rule title
				Rule description
				[eggs]
				--
			`),
			err: nil,
		},
		{
			// Probably not likely to happen any time soon but let's
			// make sure it is handled okay and does't crash
			name:   "No short name",
			source: "spam.io/bacon-bundle",
			annJson: hd.Doc(`
				{
					"path":[
						{"type":"var","value":"data"},
						{"type":"string","value":"policy"},
						{"type":"string","value":"foo"},
						{"type":"string","value":"bar"},
						{"type":"string","value":"deny"}
					],
					"annotations":{
						"scope":"rule",
						"title":"Rule title",
						"description":"Rule description"
					}
				}
			`),
			template: "text",
			expected: hd.Doc(`
				# Source: spam.io/bacon-bundle

				policy.foo.bar. (deny)
				Rule title
				Rule description
				--
			`),
			err: nil,
		},
		{
			name:   "No annotations",
			source: "spam.io/bacon-bundle",
			annJson: hd.Doc(`
				{
					"path":[
						{"type":"var","value":"data"},
						{"type":"string","value":"policy"},
						{"type":"string","value":"foo"},
						{"type":"string","value":"bar"},
						{"type":"string","value":"deny"}
					]
				}
			`),
			template: "text",
			expected: hd.Doc(`
				# Source: spam.io/bacon-bundle

				policy.foo.bar.deny
				(No annotations found)
				--
			`),
			err: nil,
		},
	}

	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			var a ast.AnnotationsRef
			err := json.Unmarshal([]byte(tt.annJson), &a)
			if err != nil {
				panic(err)
			}

			input := map[string][]*ast.AnnotationsRef{
				tt.source: {
					&a,
				},
			}

			buf := new(bytes.Buffer)
			err = OutputText(buf, input, tt.template)

			assert.Equal(t, tt.err, err, tt.name)
			assert.Equal(t, tt.expected, buf.String(), tt.name)
		})
	}
}

func TestTextOutputIsSorted(t *testing.T) {
